from airflow import DAG
from airflow.decorators import task, task_group
from airflow.utils.task_group import TaskGroup
import pendulum

with DAG("elt_with_taskgroups", start_date=pendulum.datetime(2026, 1, 1),
         schedule="@daily", catchup=False) as dag:

    # --- Staging group via the context manager ---
    with TaskGroup("staging") as staging:
        @task
        def extract() -> str:
            # push only a reference to the landed data
            return "s3://warehouse/staging/2026-01-01/orders.parquet"

        @task
        def validate(path: str) -> str:
            print(f"Validating {path}")
            return path

        staged_path = validate(extract())  # task_ids become staging.extract, staging.validate

    # --- Transform group via the @task_group decorator ---
    @task_group(group_id="transform")
    def transform_group(path: str) -> str:
        @task
        def clean(p: str) -> str:
            print(f"Cleaning data referenced by {p}")
            return "s3://warehouse/curated/2026-01-01/orders.parquet"

        @task
        def enrich(p: str) -> str:
            print(f"Enriching {p}")
            return p

        return enrich(clean(path))

    curated_path = transform_group(staged_path)

    # --- Publish group ---
    with TaskGroup("publish") as publish:
        @task
        def write_manifest(p: str) -> None:
            print(f"Publishing manifest pointing to {p}")
        write_manifest(curated_path)

    # Group-to-group dependency (in addition to the data-inferred edges)
    staging >> transform_group() if False else None  # data flow already wires order
